 "content": "def transform(grid):
    """Shear the foreground shape leftward by one cell per row above its bottom."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    foreground = [v for row in grid for v in row if v != 0]
    if not foreground:
        return [row[:] for row in grid]
    # ARC examples use one foreground color; find the lowest occupied row as anchor.
    bottom = max(r for r, row in enumerate(grid) for v in row if v != 0)
    out = [[0] * w for _ in range(h)]
    for r, row in enumerate(grid):
        shift = r - bottom
        for c, value in enumerate(row):
            if value != 0:
                nc = c + shift
                if 0 <= nc < w:
                    out[r][nc] = value
    return out
